import SwiftUI
@main struct ApexAdBlockerApp:App{@StateObject private var dns=DNSSettingsController();var body:some Scene{WindowGroup{VStack(spacing:22){Image(systemName:dns.enabled ? "checkmark.shield.fill":"shield").font(.system(size:64));Text("Apex Studio Ad Blocker").font(.title2.bold());Text(dns.enabled ? "System-wide DNS protection is active.":"System-wide protection is not active.").multilineTextAlignment(.center);Button(dns.configured ? "Reinstall / Refresh":"Install Ad Blocker"){dns.install()}.buttonStyle(.borderedProminent);if dns.configured{Button("Remove Configuration",role:.destructive){dns.remove()}};Text("After installation, enable Apex Studio Ad Blocker in iOS Settings under General → VPN & Device Management / DNS.").font(.footnote).multilineTextAlignment(.center).foregroundStyle(.secondary);if let error=dns.errorMessage{Text(error).font(.footnote).foregroundStyle(.red)}}.padding(28)}}}}
